\cite[Theorem 2.3]{li2019compositional}\label{liExample}
	We take	
	\begin{enumerate}[(1)]
		\item $ A={\mathbb F}_q $;
		\item $f(x)=x^rh\left(x^s\right) $ permutes $ {\mathbb F}_q  $, where $ s \mid (q-1), \gcd(r,q-1) =1 $ and $ h(0) \ne 0 $;
		\item $ \phi(x) =\overline{\phi}(x)= \left( x^{q-s}, x^s \right)$;
		\item $ \phi(A)=\overline{\phi}(A) $;                                          
		\item $ \psi(y,z)=\left(y^{r} h(z)^{q-s}, z^{r} h(z)^{s}\right) $; and
		\item Let $l(x)$ be the compositional inverse of $g(x)=x^rh(x)^s$ over $\mu_{\frac{q-1}{s}} =\left\{x\in{{\mathbb F}}_{q}^*: x^\frac{q-1}{s}=1\right\}$  and $r'$ be an integer which satisfies $rr'\equiv1\pmod {q-1}$.
	\end{enumerate}
	Then it follows from Theorem \ref{main} that $$f^{-1}(x)=\left(\alpha(x) h(l(\beta(x)))^{s-1}\right)^{r^{'}}l(\beta(x))$$ is the compositional inverse of $ f(x) $, where $\alpha(x)=x^{q-s}$ and $\beta(x)=x^s$.

\cite[Theorem 3.7]{niu2019new}\label{niuExample}
	Assume that
	\begin{enumerate}[(1)]
		\item $ A={\mathbb F}_{q^m} $;
		\item $ f(x) = g\left(x^{q^i} - x + \delta\right) + cx \in {\mathbb F}_{q^m}[x] $ permutes $ {\mathbb F}_{q^m} $, where $q$ is a prime power, $m,i$ be positive integers with $ 1 \le i \le m-1 $, $ c \in {\mathbb F}_{q^{\gcd(i,m)}}^* $ and $ g(x) \in {\mathbb F}_{q^m}[x] $.                   
		Then $ h(x) = g(x)^{q^i} - g(x) + cx +(1-c)\delta \in {\mathbb F}_{q^m}[x]$ permutes $ {\mathbb F}_{q^m} $ (see \cite[Proposition 3]{zheng2019two}), where $ \delta\in {\mathbb F}_{q^m} $.
		\item $ \phi(x) =\overline{\phi}(x)=\left( -x^{q^i}, x^{q^i}-x+\delta \right) $;
		\item $  \phi(A)=\overline{\phi}(A) $;                                 
		\item $ \psi(y,z)=\left(c^{q^i}y-g(z)^{q^i}, h(z) \right)$; and
		\item Assume $H(x)$ is the compositional inverse of $ h(x) $.
	\end{enumerate}
	Then it follows from Theorem \ref{main} that, for any $ \delta \in {\mathbb F}_{q^m} $, the compositional inverse of $ f(x) $ is
	$$f^{-1}(x)= c^{-1}x^{q^i} - c^{-1}g\left(H(x^{q^i}-x+\delta)\right)^{q^i} -H(x^{q^i}-x+\delta)+\delta.$$

\cite[Theorem 1.2]{tuxanidy2014inverses}
	\label{tuxanidy2014inverses}
	Let
	\begin{enumerate}[(1)]
		\item $ A={\mathbb F}_{q^n} $;
		\item $f(x)=h(\psi_0(x)) \varphi_0(x)+g_0(\psi_0(x))$ permute {${\mathbb F}_{q^n}$}, where  $ {\varphi_0}, \psi_0 \in {\mathbb F}_{q^n}[x] $ are additive polynomials, $ q $-polynomial $ \overline{\psi_0} $ satisfies $ \varphi_0 \circ \psi_0=\overline{\psi_0} \circ \varphi_0 $ and $ \left|\psi_0\left({{\mathbb F}_{q^{n}}}\right)\right|=\left|\overline{\psi_0}\left( {{\mathbb F}_{q^{n}}}\right)\right| $, and polynomial $ h \in {\mathbb F}_{q^n}[x] $ such that $ h\left(\psi_0\left(\mathbb{F}_{q^{n}}\right)\right) \subseteq \mathbb{F}_{q} \backslash\{0\} $;
		\item $ \phi(x) =\phi_{\psi_0}\left(  x \right) =\left( \psi_0(x), x-\psi_0(x) \right)$, $ \overline{\phi}=\phi_{\overline{\psi_0}}\left( x   \right) = \left( \overline{\psi_0}(x), x-\overline{\psi_0}(x) \right) $  in \cite[Lemma 2.10]{tuxanidy2014inverses};
		\item $ \phi(A)=\phi_{\psi_0}\left(\mathbb{F}_{q^{n}}\right) ,\overline{\phi}(A)=\phi_{\overline{\psi_0}}\left(\mathbb{F}_{q^{n}}\right) $;
		\item $ \psi(y,z)=\left(h(y) \varphi_0(y)+\overline{\psi_0}(g_0(y)), h(y) \varphi_0(z)+g_0(y)-\overline{\psi_0}(g_0(y)) \right)$; and
		\item Assume that $ \left|S_{\psi_0}\right|=\left|S_{\overline{\psi_0}}\right| $ and $\ker(\varphi_0) \cap \psi_0\left(S_{\psi_0}\right)=\{0\} $.
		Then $ \varphi_0 $ induces a bijection from $ S_{\overline{\psi_0}} $ to $ S_{\overline{\psi_0}} $.
		Let $ \overline{f}^{-1}$ and $\left.\varphi_0^{-1}\right|_{S_{\overline{\psi_0}}} \in {\mathbb F}_{q^{n}}[x] $ induce the inverses of $ \left.\overline{f}\right|_{\psi_0\left(\mathbb{F}_{q^n}\right)} (x)  =h(x) \varphi_0(x)+\overline{\psi_0}(g_0(x)) $ and $ \varphi_0 |_{S_{\psi_0}} $ respectively,
	\end{enumerate}
	Then it follows from Theorem \ref{main} that the compositional inverse of $ f(x) $ is given by
	$$ f^{-1}(x)=\overline{f}^{-1}(\overline{\psi_0}(x))+\left.\varphi_0^{-1}\right|_{S_{\overline{\psi_0}}}\left(\frac{x-\overline{\psi_0}(x)-g_0\left(\overline{f}^{-1}(\overline{\psi_0}(x))\right)+\overline{\psi_0}\left(g_0\left(\overline{f}^{-1}(\overline{\psi_0}(x))\right)\right)}{h\left(\overline{f}^{-1}(\overline{\psi_0}(x))\right)}\right) .$$

\cite[Theorem 2.3]{wu2013compositional} \label{wuExample}
	Let
	\begin{enumerate}[(1)]
		\item $ A={\mathbb F}_{q^n} $, where $ q $ is even and $ n $ is odd;
		\item $f(x)=x(L({\rm Tr}_{q^n/q} (x))+a {\rm Tr}_{q^n/q} (x)+a x)$ permute $ {\mathbb F}_{q^n} $, where $ xL(x) $ is a bilinear PP over $ {\mathbb F}_q $ for a linearized polynomial $ L(x) \in {\mathbb F}_q [x] $, $ a \in {\mathbb F}_q^* $, and the trace function from ${\mathbb F}_{q^n}$ to ${\mathbb F}_{q}$ is denoted by ${\rm Tr}_{q^n/q}(\cdot): x \to \sum_{i=0}^{n-1}x^{q^i}$;
		\item $ \phi(x) =\overline{\phi}(x)=\left( {\rm Tr}_{q^n/q}(x), x + {\rm Tr}_{q^n/q}(x) \right)$;
		\item $ \phi(A)=\overline{\phi}(A)={\mathbb F}_{q} \oplus  { \ker( {\rm Tr}_{q^n/q})  }$;
		\item $ \psi(y,z)=\left(y L(y), a z^{2}+(L(y)+a y) z\right)$; and
		\item Let $ q = 2^m $ for a positive integer $ m $.
		Assume the compositional inverse of $ xL ( x ) $ is $ g_0( x ) \in {\mathbb F}_q [ x ]  $.
	\end{enumerate}
	Then it follows from Theorem \ref{main} that the compositional inverse of $ f(x) $ is
	$$   f^{-1}(x)=a^{2^{m-1}-1} x^{2^{n m-1}}+\left(g_0({\rm Tr}_{q^n/q}(x))+a^{2^{m-1}-1} \sum_{k=1}^{\frac{n-1}{2}} x^{2^{(2 k-1) m-1}}\right)                                                         $$
	$$ {\times} \left(\frac{{\rm Tr}_{q^n/q}(x)}{g_0({\rm Tr}_{q^n/q}(x))}+ag_0({\rm Tr}_{q^n/q}(x))\right)^{q-1}    $$
	$$  +\sum_{j=0}^{m-2} a^{2^{j}-1}\left(\frac{{\rm Tr}_{q^n/q}(x)}{g_0({\rm Tr}_{q^n/q}(x))}+ag_0({\rm Tr}_{q^n/q}(x))\right)^{2^{m}-2^{j+1}}\left(\sum_{k=0}^{\frac{n-1}{2}} x^{q^{2 k}}\right)^{2^{j}}.  $$

