\cite[Lemma 2.1]{zieve2009some}
\label{Cri}
Let $q$ be a prime power and $f(x)=x^rh\left(x^s\right) \in{\mathbb F}_q[x]$, where $s=\frac{q-1}{\ell}$ and $\ell $ is an integer.
Then $f(x)$ permutes ${\mathbb F}_q$ if and only if
\begin{enumerate}[(1)]
	\item $\gcd\left(r,s\right)=1$ and
	\item $g(x)=x^rh(x)^s$ permutes $\mu_{\ell},$ where $\mu_{\ell}=\left\{x\in{{\mathbb F}}_{q}^*  : ~~ x^{\ell}=1\right\}$.
\end{enumerate}

Let $\phi$ be a map defined by $$\phi: {\mathbb F}_q \to \phi({\mathbb F}_q),$$ $$x\mapsto \left( \lambda(x), \eta (x) \right) = \left(x^{s},x^r\right),$$
where $\phi({\mathbb F}_q)=\left\{ \left( x^{s}, x^{r} \right):  ~~ x\in {\mathbb F}_{q}  \right\} .$

Given one element $\left( y,z\right)\in \phi({\mathbb F}_q)$, there exists $x_0\in{\mathbb F}_{q}$ such that $y=x_0^s$ and $z=x_0^r$.
Furthermore, it is clear that $y^az^b = x_0^{as+br}=x_0$.
Thus $\phi$ is a bijection and $ \phi^{-1}(y,z)=y^az^b $.


Next, we compute the expression of $\psi$ {from the relation $\psi \circ \phi(x) =\phi \circ f(x) $}.
From a simple computation, we get
\begin{equation}
	\label{mul1c}
	\phi \circ f(x) = \left(   x^{sr}h(x^s)^s ,  x^{r^2}h(x^s)^r  \right).
\end{equation}
Substituting $ x^s $ and $ x^r $ in Eq. (\ref{mul1c}) with $ y $ and $ z $ respectively, we obtain
$$\psi(y,z): \phi({\mathbb F}_q) \to \phi({\mathbb F}_q),$$
$$(y,z) \mapsto\left(y^rh(y)^s, z^rh(y)^r \right).$$




Now we compute the compositional inverse of $\psi$.

For $(y,z), (\alpha,\beta)\in \phi({\mathbb F}_q)$ with $ \psi(y,z)=(\alpha,\beta) $, we have
\begin{equation*}
	\left\{
	\begin{aligned}
		y^rh(y)^s &=& \alpha,  \\
		z^rh(y)^r &=& \beta. \\
	\end{aligned}
	\right.
\end{equation*}
Then we get $$y=g^{-1}(\alpha).$$
Moreover,
\begin{equation}
	z^r=\beta h(y)^{-r} = \beta h\left( g^{-1}(\alpha)\right)^{-r}.    \label{zzz}
\end{equation}






Clearly, for any given $(\alpha, \beta)\in\phi({\mathbb F}_q)$, there exists a unique element denoted by {${x_{(\alpha,\beta)}}\in{\mathbb F}_q$} such that $ \alpha={x_{(\alpha,\beta)}}^s$  and $ \beta={x_{(\alpha,\beta)}}^r $.
Therefore, $z^r = \beta h\left( g^{-1}(\alpha)\right)^{-r} = {x_{(\alpha,\beta)}}^rh\left( g^{-1}({x_{(\alpha,\beta)}}^s)  \right)^{-r}$. To show that $z= x_{(\alpha,\beta)}h\left( g^{-1}({x_{(\alpha,\beta)}}^s)  \right)^{-1} $ is the unique solution to Eq. (\ref{zzz}), it suffices to prove that $x_{(\alpha,\beta)}h\left( g^{-1}({x_{(\alpha,\beta)}}^s)  \right)^{-1} \in \{x^r: ~~ x \in {\mathbb F}_q\}$.



Since $f$ is a PP, there exists a unique $x_0\in{\mathbb F}_q$ such that $ {x_{(\alpha,\beta)}}=f(x_0)=x_0^r h\left(x_0^s\right)  $.
Furthermore, we have $$g^{-1}(f(x_0)^s) =g^{-1}(x_0^{rs}h(x_0^s)^s) = g^{-1}(g(x_0^s)) = x_0^s. $$
Plugging ${x_{(\alpha,\beta)}}=x_0^r h\left(x_0^s\right)$ into $ {x_{(\alpha,\beta)}}h\left(  g^{-1}({x_{(\alpha,\beta)}}^s)  \right)^{-1} $, we obtain $${x_{(\alpha,\beta)}}h\left(  g^{-1}({x_{(\alpha,\beta)}}^s)  \right)^{-1} = x_0^{r} h\left(x_0^s\right) h(g^{-1}(f(x_0)^s))^{-1} = x_0^r h\left(x_0^s\right) h\left(x_0^s\right)^{-1} =x_0^r,$$ which belongs to $\{x^r: ~~ x \in {\mathbb F}_q\}$.
Thus $ z={x_{(\alpha,\beta)}}h\left(  g^{-1}({x_{(\alpha,\beta)}}^s)  \right)^{-1} $ and then $$\psi^{-1}\left(\alpha,\beta \right)=\left( g^{-1}(\alpha), {x_{(\alpha,\beta)}}h\left(  g^{-1}({x_{(\alpha,\beta)}}^s)  \right)^{-1} \right).$$








{According to Theorem \ref{main},  the compositional inverse of $ f(x) $ is
$$f^{-1}(x)={\phi}^{-1} \circ \psi^{-1} \circ {\phi}(x)= g^{-1}(\alpha)^a  z^b  = g^{-1}(x^s)^a x^b h\left(g^{-1}(x^s)\right)^{-b}.$$}

\label{mulinvolution}

The PP $f(x) = x^rh(x^s) $ over ${\mathbb F}_q$ defined as in Lemma \ref{Cri} is an involution if and only if
\begin{enumerate}[(1)]
	\item $g(x)=x^rh(x)^s$ is involutory on $\mu_{\frac{q-1}{s}}$ and
	\item $\varphi(x)=g(x^s)^a x^{b-r} h\left(g(x^s)\right)^{-b}h(x^s)^{-1}= 1 $ holds for any $ x \in {\mathbb F}_q^* $, where integers $ a $ and $b $ satisfy $ as+br=1 $.
\end{enumerate}

\cite[Corollary 2.17]{niu2019new}
	\label{kuozhancor}
Let $q$ be a power of $2$ and $ k $ be a positive integer such that $ \gcd(k,q+1)=1 $.
Then for any $\gamma , \beta  \in {\mathbb F}_q^*$ such that $ {\rm Tr}_{q/2}(\beta)=0 $, the polynomial $f(x)=x^{q^2-2}h\left(x^{q-1}\right)$ is an involution on ${\mathbb F}_{q^2}$, where $h(x)=\gamma\left(  x^{-1}+\beta x^{-k-1}+\beta x^{k-1}\right) $.

According to the proof of \cite[Corollary 2.17]{niu2019new}, we obtain $h(x) \ne 0$ and $g(x)=x^{-1}h(x)^{q-1}=x$, for any $ x \in \mu_{q+1} $.
	{
Let $a= -1,   b= -q, r=-1, s=q-1$ in Corollary \ref{mulinvolution}.
	Then $\varphi(x)=x^{1-q} x^{-q+1} h\left(x^s\right)^{q}h(x^s)^{-1}=  x^{1-q} (x^{-q+1} h(x^{q-1})^{q-1}) = x^{1-q} x^{q-1} = 1$.
}	Thus $f$ is an involution.

Let $ L(x) $ be a linearized PP over $F$ and $\phi,\overline{\phi}$ be maps defined by $$\phi: F \to \phi(F) $$ $$ x   \mapsto \left( \lambda(x),  L(x)-\lambda(x) \right) ,$$
and $$ \overline{\phi}: F \to \overline{\phi}(F) $$ $$x \mapsto \left( \overline{\lambda}(x),  L(x)-\overline{\lambda}(x) \right) .$$

Then $\phi$ and $ \overline{\phi} $ are bijections, and for $(y,z)\in \phi(F)$,  we have $\phi^{-1}(y,z)=L^{-1}(y+z)$,                                                                                             
where {$\phi^{-1}$} and $ L^{-1} $ denote the compositional inverses of {$\phi$} and $ L $ respectively.
Here is the commutative diagram as stated in Theorem \ref{main}.

\begin{equation*}
	\xymatrix{
		F \ar[rr]^{f=g + g_0\circ\lambda }\ar[d]_{\phi=(\lambda, \eta)} &   &  F  \ar[d]^{\overline{\phi}=(\overline{\lambda}, \overline{\eta})} \\
		\phi(F)	 \ar[rr]^{\psi=(g,\tau)} &  & \overline{\phi}(F) }
\end{equation*}



Next,   we find the map $\psi$ such that  $ \psi \circ \phi =\overline{\phi} \circ f  $.
After direct calculation, we have
\begin{equation}
	\label{additive1c}
	\overline{\phi}\circ f(x)=\left( g(\lambda(x)),    L \left(  g(x) \right) + L\left(  g_0(\lambda(x)) \right) -g(\lambda(x)) \right).
\end{equation}
To compute $ \psi(y,z) $ accordingly such that $\bar{\phi}\circ f(x)=\psi\circ \phi (x)$, we substitute $ \lambda(x) $ and $ L(x)-\lambda(x) $ in Eq. (\ref{additive1c}) with $ y $ and $ z $ respectively.
We obtain
$$\psi(y,z): \phi(F) \to \overline{\phi}(F),$$
$$(y,z) \mapsto\left( g(y), L(g(L^{-1}(y+z)))+ L( g_0(y) ) - g(y) \right).$$	

Clearly $\psi $ is a bijection, since $\psi \circ \phi(x) =\phi \circ f(x) $.
Now we compute the compositional inverse of $\psi$.
Since $ f $ permutes $ F $, $ g $ permutes $ F $, and we assume that $g^{-1}$ is the compositional inverse of $g$.
For any $(y,z)\in\phi(F)$ with $ \psi(y,z)=(\alpha,\beta) \in \overline{\phi}(F) $, we have
\begin{equation*}
	\left\{
	\begin{aligned}
		g(y)&=& \alpha,  \\
		L(g(L^{-1}(y+z)))+ L( g_0(y) ) - g(y)&=& \beta.  \\
	\end{aligned}
	\right.
\end{equation*}
Clearly, $$y=g^{-1}(\alpha).$$
Moreover,
\begin{equation}
	\label{YD112eq}
	L(g(L^{-1}(y+z)))=\alpha+ \beta-L( g_0(y) ).
\end{equation}
Composing $ L \circ g^{-1} \circ L^{-1} $ on Eq. (\ref{YD112eq}) and simplifying it, we have
\begin{equation*}
	z=L \left(  g^{-1} \left(        L^{-1}  ( \alpha+ \beta  )-  g_0(g^{-1}(\alpha)) \right)    \right)   - g^{-1}(\alpha).
\end{equation*}
Hence we have	$$\psi^{-1}\left(\alpha,\beta \right)=\left( g^{-1}(\alpha) ,   L \left(  g^{-1} \left(        L^{-1}  ( \alpha+ \beta  )-  g_0(g^{-1}(\alpha)) \right)    \right)   - g^{-1}(\alpha)        \right) .$$




Finally we compute the compositional inverse of $ f(x) $.
According to Theorem \ref{main},  together with                                                                       
$\alpha = \overline{\lambda}(x)$ and $\beta=L(x) -\overline{\lambda}(x)$, we obtain the compositional inverse of $ f(x) $ is
$$f^{-1}(x)={\phi}^{-1} \circ \psi^{-1} \circ \overline{\phi}(x)=  g^{-1} \left(        L^{-1}  ( \alpha+ \beta  )-  g_0(g^{-1}(\alpha)) \right)  = g^{-1}\left(x-g_0(g^{-1}(\overline{\lambda}(x))) \right) .$$

\label{addinvolution1}
{In Lemma \ref{YD11}, let $\lambda=\bar{\lambda}$, $ S=\bar{S}$ be a finite subset of $ F $ such that $\lambda(F)=S$, and let $g$ be a bijection from $S$ to $S$.}
Then, the PP $ f(x) = g (x) + g_0(\lambda(x)) $ over $F$ defined as in Lemma \ref{YD11} is an involution if and only if
{$\varphi(x)=g^{-1}\left(x-g_0(g({\lambda}(x))) \right) - g (x) -g_0(\lambda(x)) = 0 $ holds for any $x\in F$}.

\cite[Theorem 6.3]{akbary2011constructing}
\label{2-6.3}
Let $ q $ be any power of the prime number $ p $, let $ n $ be any positive integer, and let $ S $ be any subset of $ {\mathbb F}_{q^n} $ containing 0.
Let $ h,k \in {\mathbb F}_{q^n}$ be any polynomials such that $ h(0) \ne 0 $ and $ k(0) = 0 $, and let $ {\lambda(x)} \in {\mathbb F}_{q^n}[x]  $ be any polynomial satisfying
\begin{enumerate}[(1)]
\item $h(\lambda({\mathbb F}_{q^n})) \subseteq S$; and
\item $ \lambda(a\alpha) = k(a) \lambda(\alpha) $ for all $ a \in S $ and all $ \alpha \in {\mathbb F}_{q^n}$.
\end{enumerate}
Then the polynomial $ f (x) = xh(\lambda(x)) $ is a permutation polynomial for $ {\mathbb F}_{q^n} $ if and only if $ g(x) = xk(h(x)) $ induces a permutation of $ \lambda({\mathbb F}_{q^n}) $.

Let  $\eta(x) = x-\lambda(x)$ and $\phi$ be a map defined by $$\phi: {\mathbb F}_{q^n} \to \phi({\mathbb F}_{q^n}),$$ $$x \mapsto \left( \lambda(x),  x-\lambda(x) \right) .$$
Then $\phi$ is a bijection and for $(y,z)\in \phi({\mathbb F}_{q^n}),\ \phi^{-1}(y,z)=y+z.$
Let us consider the following commutative diagram.
\begin{equation*}
\xymatrix{
{\mathbb F}_{q^n} \ar[rr]^{f(x)=xh(\lambda(x))}\ar[d]_{\phi=(\lambda, \eta)} &   &  {\mathbb F}_{q^n}  \ar[d]^{\phi=(\lambda, \eta)} \\
\phi({\mathbb F}_{q^n})	 \ar[rr]^{\psi=(g,\tau)} &  & \phi({\mathbb F}_{q^n}) }
\end{equation*}

First we determine the expression of $\psi$ to {establish the connection} ${\phi}\circ f(x)=\psi\circ \phi (x)$. After direct computation, we have
\begin{equation}
\label{combi1c}
\phi \circ f(x)=\left(\lambda(x)k(h(\lambda(x))), xh(\lambda(x))-k(h(\lambda(x)))\lambda(x) \right) .
\end{equation}



Then, substituting $ \lambda(x) $ and $ x-\lambda(x) $ in Eq. (\ref{combi1c}) with $ y $ and $ z $ respectively, we obtain
$$\psi(y,z): \phi({\mathbb F}_{q^n}) \to \phi({\mathbb F}_{q^n}),$$
$$(y,z) \mapsto\left(yk(h(y)), (y+z)h(y)-k(h(y))y \right).$$	

Since $f(x)=xh(\lambda(x))$ permutes ${\mathbb F}_{q^n}$, we have that both $\psi$ and $g(x) = xk(h(x))$ are bijective.
Recall that $ g^{-1} $ denotes the compositional inverse of $ g(y) = yk(h(y)) $ over $\lambda({\mathbb F}_{q^n})$.
In the following, we compute the compositional inverse of $\psi$.
Let $(y,z), (\alpha,\beta)\in \phi({\mathbb F}_{q^n}),$ satisfy $ \psi(y,z)=(\alpha,\beta) $, i.e.,
\begin{equation}
\left\{
\begin{aligned}
yk(h(y))&=& \alpha, \label{Bk2y} \\
(y+z)h(y)-k(h(y))y&=& \beta.  \\
\end{aligned}
\right.
\end{equation}
Then, we have $$y=g^{-1}(\alpha).$$
Moreover, for $ z $, we firstly explain $ h(y) \ne 0 $ for any $ y \in \lambda({\mathbb F}_{q^n}) $.
Assume that there exists some $ y_0 \in \lambda({\mathbb F}_{q^n}) $ such that $ h(y_0) = 0 $.
We have $ g(y_0) = y_0k(h(y_0)) =0$ and $ g(0) =0 $.
Since $ g(y) $ is bijective, we have $ y_0 =0 $, which is conflict with $ h(0) \ne 0 $.
Thus $ h(y) \ne 0 $ for any $ y \in \lambda({\mathbb F}_{q^n}) $.
Then it follows from Eq.(\ref{Bk2y}) that
\begin{equation*}
\label{Bk2eq}
z= \frac{\beta + k\left(h\left( y \right)\right) y}{h\left(y  \right)}-y.
\end{equation*}
Hence,  we have
$$\psi^{-1}\left(\alpha,\beta \right)=\left( g^{-1}(\alpha) ,   \frac{\beta + k\left(h\left(g^{-1}(\alpha)\right)\right)g^{-1}(\alpha)}{h\left(g^{-1}(\alpha)\right)}-g^{-1}(\alpha) \right).$$


Finally, we compute the compositional inverse of $ f(x) $.
From Theorem \ref{main}, together with the compositional inverses of $\phi, \psi$ and $\alpha = \lambda(x)$, $\beta=x-\lambda(x)$, the compositional inverse of $ f(x) $ is

\begin{equation*}
\begin{aligned}
f^{-1}(x)&= {\phi}^{-1} \circ \psi^{-1} \circ {\phi}(x)     \\
&=   g^{-1}(\alpha) + \frac{\beta + k\left(h\left(g^{-1}(\alpha)\right)\right)g^{-1}(\alpha)}{h\left(g^{-1}(\alpha)\right)} - g^{-1}(\alpha)   \\
&=  \frac{x-\lambda(x) + k\left(h\left(g^{-1}\left(\lambda(x)\right)\right)\right)g^{-1}\left(\lambda(x)\right)}{h\left(g^{-1}\left(\lambda(x)\right)\right)}.
\end{aligned}
\end{equation*}

Since $ f(0)=0 $, we only need to consider the nonzero situation.
{Assume $f$ is an involution. By Lemma \ref{maininvolution}}, we have $g$ is an involution, which is equivalent to $ \theta \left(  \theta(y)   y    \right)   \theta(y)   = k\left(h\left(  k(h(y))   y    \right)\right)   k(h(y)) =1 $ for $ y \in \lambda({\mathbb F}_{q^n}^*) $.
{From now on, we assume (1) hold and    prove that $f$ is an involution if and only if  $\varphi(x)=0  $.}
Plugging {$$ k\left(h\left(  k(h(y))   y    \right)\right)   k(h(y)) =1 $$ for $ y \in \lambda({\mathbb F}_{q^n}^*) $}, $ g^{-1}(x)= g(x) $ and $ f^{-1}(x)  $ by {Theorem \ref{mainBk}} into $ \varphi(x) $, we have
\begin{eqnarray*}
